import math
r=lambda d:math.radians(d)
res=math.tan(r(55))/(1/math.tan(r(35)))
opts={'A':1,'B':1/math.cos(r(55)),'C':0,'D':math.cos(r(35))}
for k,v in opts.items():
    assert (abs(res-v)<1e-9)==(k=='A')

import math
A=0.7
lhs=math.sin(A)/(1+math.cos(A))+1/math.tan(A)
opts={'A':math.sin(A)+math.cos(A),'B':math.cos(A),'C':math.sin(A),'D':1/math.sin(A)}
for k,v in opts.items():
    assert (abs(lhs-v)<1e-9)==(k=='D')

